content:
Save this as `index.html` and open it in a modern browser. It uses only the Three.js core ES module from cdnjs, with custom camera controls and no external assets.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Bamboo Box Kite</title>

  <style>
    :root {
      color-scheme: light;
      --ink: #263b43;
      --muted: #60747a;
      --paper: rgba(255, 252, 240, 0.78);
      --line: rgba(38, 59, 67, 0.16);
      --accent: #b94738;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #dce9ed;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    #scene {
      position: fixed;
      inset: 0;
    }

    #scene canvas {
      display: block;
      width: 100%;
      height: 100%;
      outline: none;
      touch-action: none;
      cursor: grab;
    }

    #scene canvas:active {
      cursor: grabbing;
    }

    .vignette {
      position: fixed;
      inset: 0;
      pointer-events: none;
      background:
        radial-gradient(circle at 50% 44%, transparent 45%, rgba(44, 68, 76, 0.08) 100%),
        linear-gradient(to bottom, rgba(255, 255, 255, 0.12), transparent 28%);
    }

    .heading {
      position: fixed;
      top: clamp(22px, 4vw, 48px);
      left: clamp(22px, 4vw, 52px);
      max-width: 360px;
      pointer-events: none;
      text-shadow: 0 1px 16px rgba(255, 255, 255, 0.55);
    }

    .eyebrow {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 10px;
      color: var(--accent);
      font-size: 11px;
      font-weight: 750;
      letter-spacing: 0.2em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      width: 30px;
      height: 1px;
      content: "";
      background: currentColor;
    }

    h1 {
      margin: 0;
      color: var(--ink);
      font-family: Georgia, "Times New Roman", serif;
      font-size: clamp(38px, 5.5vw, 72px);
      font-weight: 400;
      line-height: 0.95;
      letter-spacing: -0.045em;
    }

    .subtitle {
      max-width: 300px;
      margin: 18px 0 0;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.6;
    }

    .wind-card {
      position: fixed;
      right: clamp(18px, 3vw, 38px);
      top: clamp(22px, 4vw, 42px);
      display: flex;
      align-items: center;
      gap: 12px;
      min-width: 145px;
      padding: 12px 15px;
      border: 1px solid var(--line);
      border-radius: 14px;
      background: var(--paper);
      box-shadow: 0 12px 35px rgba(42, 66, 74, 0.09);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      color: var(--muted);
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.13em;
      text-transform: uppercase;
    }

    .wind-bar {
      width: 42%;
      height: 2px;
      overflow: hidden;
      border-radius: 2px;
      background: rgba(38, 59, 67, 0.12);
    }

    .wind-bar::after {
      display: block;
      width: 68%;
      height: 100%;
      content: "";
      background: var(--accent);
      animation: wind 1.7s ease-in-out infinite;
    }

    @keyframes wind {
      from {
        transform: translateX(-10%);
      }
      to {
        transform: translateX(135%);
      }
    }

    .controls {
      position: fixed;
      right: clamp(18px, 3vw, 38px);
      bottom: clamp(18px, 3vw, 32px);
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .hint {
      padding: 10px 13px;
      border: 1px solid var(--line);
      border-radius: 12px;
      background: var(--paper);
      color: var(--muted);
      font-size: 11px;
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
    }

    button {
      min-height: 40px;
      padding: 0 16px;
      border: 1px solid rgba(38, 59, 67, 0.2);
      border-radius: 12px;
      background: #f8f3e7;
      color: var(--ink);
      font: inherit;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.06em;
      cursor: pointer;
      box-shadow: 0 8px 24px rgba(42, 66, 74, 0.09);
      transition:
        transform 160ms ease,
        background 160ms ease;
    }

    button:hover {
      background: #fffdf6;
      transform: translateY(-1px);
    }

    button:active {
      transform: translateY(0);
    }

    button:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 3px;
    }

    .corner-mark {
      position: fixed;
      left: clamp(22px, 4vw, 52px);
      bottom: clamp(22px, 4vw, 42px);
      color: rgba(38, 59, 67, 0.42);
      font-family: Georgia, "Times New Roman", serif;
      font-size: 12px;
      pointer-events: none;
    }

    @media (max-width: 640px) {
      .subtitle {
        max-width: 230px;
        font-size: 12px;
      }

      .wind-card {
        top: auto;
        right: 18px;
        bottom: 76px;
        min-width: 120px;
        padding: 10px 12px;
      }

      .hint {
        display: none;
      }

      .corner-mark {
        display: none;
      }
    }
  </style>
</head>

<body>
  <main id="scene" aria-label="Interactive three-dimensional bamboo box kite"></main>
  <div class="vignette" aria-hidden="true"></div>

  <header class="heading">
    <div class="eyebrow">Traditional wind craft</div>
    <h1>Bamboo<br />Box Kite</h1>
    <p class="subtitle">
      A lattice-built paper kite, woven with natural bamboo ribs, lacquered panels,
      and a fine control line.
    </p>
  </header>

  <aside class="wind-card" aria-label="Wind conditions">
    <span>Wind</span>
    <div class="wind-bar"></div>
  </aside>

  <div class="corner-mark">Hand-framed · Hand-fired</div>

  <div class="controls">
    <div class="hint">Drag to orbit · Scroll to zoom · Double-click to reset</div>
    <button id="reset" type="button">Reset view</button>
  </div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    const host = document.getElementById("scene");
    const resetButton = document.getElementById("reset");
    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    // ---------------------------------------------------------------------
    // Renderer and scene
    // ---------------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: false,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.domElement.tabIndex = 0;
    renderer.domElement.setAttribute(
      "aria-label",
      "Drag to orbit the bamboo kite. Use the mouse wheel to zoom."
    );
    host.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.fog = new THREE.Fog(0xdce8eb, 11, 28);

    const camera = new THREE.PerspectiveCamera(
      40,
      window.innerWidth / window.innerHeight,
      0.1,
      80
    );

    const hemisphere = new THREE.HemisphereLight(0xe9f5ff, 0x9a7650, 2.15);
    scene.add(hemisphere);

    const sunLight = new THREE.DirectionalLight(0xfff0d2, 3.2);
    sunLight.position.set(-5, 9, 6);
    sunLight.castShadow = true;
    sunLight.shadow.mapSize.set(1024, 1024);
    sunLight.shadow.camera.left = -7;
    sunLight.shadow.camera.right = 7;
    sunLight.shadow.camera.top = 7;
    sunLight.shadow.camera.bottom = -7;
    sunLight.shadow.camera.near = 0.5;
    sunLight.shadow.camera.far = 25;
    sunLight.shadow.bias = -0.0005;
    scene.add(sunLight);

    const fillLight = new THREE.DirectionalLight(0xb9d9ee, 0.85);
    fillLight.position.set(6, 3, -7);
    scene.add(fillLight);

    // ---------------------------------------------------------------------
    // Procedural sky
    // ---------------------------------------------------------------------

    function createSkyTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = 16;
      canvas.height = 512;

      const context = canvas.getContext("2d");
      const gradient = context.createLinearGradient(0, 0, 0, 512);

      gradient.addColorStop(0.0, "#9fc8df");
      gradient.addColorStop(0.38, "#dce9ed");
      gradient.addColorStop(0.57, "#f0dfbd");
      gradient.addColorStop(1.0, "#b8d2d9");

      context.fillStyle = gradient;
      context.fillRect(0, 0, 16, 512);

      const sun = context.createRadialGradient(105, 110, 2, 105, 110, 55);
      sun.addColorStop(0, "rgba(255, 245, 207, 0.95)");
      sun.addColorStop(0.2, "rgba(255, 232, 181, 0.48)");
      sun.addColorStop(1, "rgba(255, 232, 181, 0)");

      context.fillStyle = sun;
      context.fillRect(45, 35, 120, 120);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      return texture;
    }

    scene.background = createSkyTexture();

    // ---------------------------------------------------------------------
    // Materials and geometry helpers
    // ---------------------------------------------------------------------

    const bambooMaterial = new THREE.MeshStandardMaterial({
      color: 0xc8a367,
      roughness: 0.58,
      metalness: 0.02
    });

    const bambooHighlightMaterial = new THREE.MeshStandardMaterial({
      color: 0xe0bf83,
      roughness: 0.5,
      metalness: 0.02
    });

    const bambooShadowMaterial = new THREE.MeshStandardMaterial({
      color: 0x9c7947,
      roughness: 0.66
    });

    const goldMaterial = new THREE.MeshStandardMaterial({
      color: 0xe4b963,
      roughness: 0.36,
      metalness: 0.48
    });

    const redMaterial = new THREE.MeshStandardMaterial({
      color: 0xa9322d,
      roughness: 0.78
    });

    const stringMaterial = new THREE.MeshStandardMaterial({
      color: 0xf0e7cf,
      roughness: 0.96
    });

    function createWeaveTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = 256;
      canvas.height = 256;

      const context = canvas.getContext("2d");
      context.fillStyle = "#fff1cf";
      context.fillRect(0, 0, 256, 256);

      for (let i = 0; i < 150; i++) {
        const x = Math.random() * 256;
        const y = Math.random() * 256;
        const length = 8 + Math.random() * 42;

        context.strokeStyle = `rgba(92, 54, 24, ${0.018 + Math.random() * 0.025})`;
        context.lineWidth = 0.5 + Math.random();
        context.beginPath();
        context.moveTo(x, y);
        context.lineTo(x + length, y + Math.random() * 0.7);
        context.stroke();
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(2, 2);
      texture.anisotropy = Math.min(
        8,
        renderer.capabilities.getMaxAnisotropy()
      );

      return texture;
    }

    const paperTexture = createWeaveTexture();

    const paperMaterial = new THREE.MeshStandardMaterial({
      map: paperTexture,
      color: 0xc94036,
      roughness: 0.86,
      metalness: 0,
      side: THREE.DoubleSide
    });

    function cylinderBetween(
      parent,
      start,
      end,
      radius,
      material,
      radialSegments = 10
    ) {
      const direction = new THREE.Vector3().subVectors(end, start);
      const length = direction.length();

      const geometry = new THREE.CylinderGeometry(
        radius,
        radius,
        length,
        radialSegments,
        1,
        false
      );

      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;

      parent.add(mesh);
      return mesh;
    }

    function addSphere(parent, position, radius, material, segments = 12) {
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(radius, segments, Math.max(6, segments / 2)),
        material
      );
      mesh.position.copy(position);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    // ---------------------------------------------------------------------
    // Bamboo box kite
    // ---------------------------------------------------------------------

    const kite = new THREE.Group();
    kite.position.set(0, 1.15, 0);
    scene.add(kite);

    const halfWidth = 2.25;
    const halfHeight = 1.65;
    const halfDepth = 0.58;

    const outerX0 = -halfWidth;
    const outerX1 = halfWidth;
    const outerY0 = -halfHeight;
    const outerY1 = halfHeight;

    // Front and back perimeter frames.
    cylinderBetween(
      kite,
      new THREE.Vector3(outerX0, outerY1, halfDepth),
      new THREE.Vector3(outerX1, outerY1, halfDepth),
      0.065,
      bambooMaterial
    );

    cylinderBetween(
      kite,
      new THREE.Vector3(outerX1, outerY1, halfDepth),
      new THREE.Vector3(outerX1, outerY0, halfDepth),
      0.065,
      bambooMaterial
    );

    cylinderBetween(
      kite,
      new THREE.Vector3(outerX1, outerY0, halfDepth),
      new THREE.Vector3(outerX0, outerY0, halfDepth),
      0.065,
      bambooMaterial
    );

    cylinderBetween(
      kite,
      new THREE.Vector3(outerX0, outerY0, halfDepth),
      new THREE.Vector3(outerX0, outerY1, halfDepth),
      0.065,
      bambooMaterial
    );

    // Side frames connect the front and back.
    cylinderBetween(
      kite,
      new THREE.Vector3(outerX0, outerY1, halfDepth),
      new THREE.Vector3(outerX0, outerY1, -halfDepth),
      0.06,
      bambooMaterial
    );

    cylinderBetween(
      kite,
      new THREE.Vector3(outerX1, outerY1, halfDepth),
      new THREE.Vector3(outerX1, outerY1, -halfDepth),
      0.06,
      bambooMaterial
    );

    cylinderBetween(
      kite,
      new THREE.Vector3(outerX0, outerY0, halfDepth),
      new THREE.Vector3(outerX0, outerY0, -halfDepth),
      0.06,
      bambooMaterial
    );

    cylinderBetween(
      kite,
      new THREE.Vector3(outerX1, outerY0, halfDepth),
      new THREE.Vector3(outerX1, outerY0, -halfDepth),
      0.06,
      bambooMaterial
    );

    // Three longitudinal bamboo ribs.
    const ribXs = [-1.35, 0, 1.35];

    for (const x of ribXs) {
      cylinderBetween(
        kite,
        new THREE.Vector3(x, 0, -halfDepth),
        new THREE.Vector3(x, 0, halfDepth),
        0.052,
        bambooHighlightMaterial
      );
    }

    // Crossbars at the front, middle, and back.
    const crossbarYs = [-1.2, 0, 1.2];
    const crossbarZs = [-halfDepth, 0, halfDepth];

    for (const y of crossbarYs) {
      for (const z of crossbarZs) {
        cylinderBetween(
          kite,
          new THREE.Vector3(outerX0, y, z),
          new THREE.Vector3(outerX1, y, z),
          0.048,
          bambooMaterial
        );
      }
    }

    // Instanced bamboo joints.
    const nodePositions = [];

    for (const x of ribXs) {
      for (let z = -halfDepth + 0.13; z <= halfDepth - 0.1; z += 0.22) {
        nodePositions.push([x, 0, z]);
      }
    }

    for (const y of crossbarYs) {
      for (const z of crossbarZs) {
        for (let x = outerX0 + 0.1; x <= outerX1 - 0.08; x += 0.34) {
          nodePositions.push([x, y, z]);
        }
      }
    }

    for (const x of [outerX0, outerX1]) {
      for (const y of [outerY0, outerY1]) {
        nodePositions.push([x, y, halfDepth + 0.015]);
        nodePositions.push([x, y, -halfDepth - 0.015]);
      }
    }

    const nodeGeometry = new THREE.SphereGeometry(0.075, 8, 6);
    const nodeMaterial = new THREE.MeshStandardMaterial({
      color: 0x8f6d3d,
      roughness: 0.72
    });

    const nodes = new THREE.InstancedMesh(
      nodeGeometry,
      nodeMaterial,
      nodePositions.length
    );

    const nodeDummy = new THREE.Object3D();

    nodePositions.forEach((position, index) => {
      nodeDummy.position.set(...position);
      nodeDummy.scale.setScalar(index === nodePositions.length - 1 ? 1.35 : 1);
      nodeDummy.updateMatrix();
      nodes.setMatrixAt(index, nodeDummy.matrix);
    });

    nodes.instanceMatrix.needsUpdate = true;
    nodes.castShadow = true;
    nodes.receiveShadow = true;
    kite.add(nodes);

    // Six lacquered paper panels.
    const panelXs = [-2.25, -1.35, 0, 1.35, 2.25];
    const panelYs = [-1.2, 0, 1.2];

    function createPanelBorder(x0, x1, y0, y1) {
      const width = x1 - x0;
      const height = y1 - y0;
      const centerX = (x0 + x1) * 0.5;
      const centerY = (y0 + y1) * 0.5;

      const geometry = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(x0, y0, 0.027),
        new THREE.Vector3(x1, y0, 0.027),
        new THREE.Vector3(x1, y1, 0.027),
        new THREE.Vector3(x0, y1, 0.027),
        new THREE.Vector3(x0, y0, 0.027)
      ]);

      const border = new THREE.LineLoop(
        geometry,
        new THREE.LineBasicMaterial({
          color: 0xf0c66f,
          transparent: true,
          opacity: 0.62
        })
      );

      kite.add(border);
    }

    for (let row = 0; row < panelYs.length; row++) {
      for (let column = 0; column < panelXs.length - 1; column++) {
        const panel = new THREE.Mesh(
          new THREE.BoxGeometry(
            panelXs[column + 1] - panelXs[column],
            panelYs[row + 1] - panelYs[row],
            0.035
          ),
          paperMaterial
        );

        panel.position.set(
          (panelXs[column] + panelXs[column + 1]) * 0.5,
          (panelYs[row] + panelYs[row + 1]) * 0.5,
          0
        );

        panel.castShadow = true;
        panel.receiveShadow = true;
        kite.add(panel);

        createPanelBorder(
          panelXs[column],
          panelXs[column + 1],
          panelYs[row],
          panelYs[row + 1]
        );
      }
    }

    // Lacquered corner caps.
    for (const x of [outerX0, outerX1]) {
      for (const y of [outerY0, outerY1]) {
        addSphere(
          kite,
          new THREE.Vector3(x, y, halfDepth + 0.025),
          0.09,
          redMaterial
        );
      }
    }

    // Hanging corner tassels.
    function createTassel(x, y, z) {
      const top = new THREE.Vector3(x, y, z);
      const middle = new THREE.Vector3(x * 0.98, y - 0.2, z + 0.025);
      const bottom = new THREE.Vector3(x * 0.96, y - 0.34, z + 0.04);

      cylinderBetween(
        kite,
        top,
        middle,
        0.018,
        goldMaterial,
        7
      );

      addSphere(kite, middle, 0.07, redMaterial);

      const tassel = new THREE.Mesh(
        new THREE.CylinderGeometry(0.025, 0.065, 0.24, 7),
        redMaterial
      );

      tassel.position.set(
        bottom.x,
        bottom.y - 0.12,
        bottom.z + 0.015
      );

      tassel.castShadow = true;
      kite.add(tassel);
    }

    createTassel(outerX0, outerY0, halfDepth);
    createTassel(outerX1, outerY0, halfDepth);
    createTassel(outerX0, outerY1, halfDepth);
    createTassel(outerX1, outerY1, halfDepth);

    // ---------------------------------------------------------------------
    // Control line and spool
    // ---------------------------------------------------------------------

    const spool = new THREE.Group();
    spool.position.set(3.25, -2.25, 1.8);
    scene.add(spool);

    const spoolBody = new THREE.Mesh(
      new THREE.CylinderGeometry(0.24, 0.24, 0.5, 24),
      stringMaterial
    );
    spoolBody.rotation.z = Math.PI / 2;
    spoolBody.castShadow = true;
    spool.add(spoolBody);

    for (const x of [-0.29, 0.29]) {
      const disc = new THREE.Mesh(
        new THREE.CylinderGeometry(0.34, 0.34, 0.07, 24),
        bambooShadowMaterial
      );
      disc.rotation.z = Math.PI / 2;
      disc.position.x = x;
      disc.castShadow = true;
      spool.add(disc);
    }

    const spoolHub = new THREE.Mesh(
      new THREE.CylinderGeometry(0.085, 0.085, 0.68, 16),
      goldMaterial
    );
    spoolHub.rotation.z = Math.PI / 2;
    spool.add(spoolHub);

    // A small marker makes the spool's rotation visible.
    const spoolMarker = new THREE.Mesh(
      new THREE.BoxGeometry(0.025, 0.18, 0.07),
      redMaterial
    );
    spoolMarker.position.set(0.315, 0.13, 0);
    spool.add(spoolMarker);

    const lineCurve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(0, -0.48, 0.12),
      new THREE.Vector3(0.35, -0.82, 0.55),
      new THREE.Vector3(1.15, -1.35, 1.05),
      new THREE.Vector3(2.2, -1.83, 1.65),
      new THREE.Vector3(2.94, -2.25, 1.8)
    ]);

    const controlLine = new THREE.Mesh(
      new THREE.TubeGeometry(lineCurve, 90, 0.009, 5, false),
      stringMaterial
    );

    controlLine.castShadow = true;
    scene.add(controlLine);

    // ---------------------------------------------------------------------
    // Clouds, distant mountains, birds, and drifting particles
    // ---------------------------------------------------------------------

    const cloudMaterial = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 1,
      transparent: true,
      opacity: 0.76,
      depthWrite: false
    });

    const clouds = [];

    function createCloud(x, y, z, scale) {
      const cloud = new THREE.Group();
      cloud.position.set(x, y, z);
      cloud.scale.setScalar(scale);

      const lobes = [
        [-0.75, 0, 0, 0.72, 0.38, 0.48],
        [-0.2, 0.12, 0, 0.88, 0.58, 0.58],
        [0.35, 0.04, 0, 0.8, 0.5, 0.52],
        [0.82, -0.04, 0, 0.62, 0.35, 0.42],
        [0.05, -0.12, 0.12, 0.72, 0.4, 0.48]
      ];

      for (const [lx, ly, lz, sx, sy, sz] of lobes) {
        const lobe = new THREE.Mesh(
          new THREE.SphereGeometry(1, 14, 10),
          cloudMaterial
        );

        lobe.position.set(lx, ly, lz);
        lobe.scale.set(sx, sy, sz);
        cloud.add(lobe);
      }

      scene.add(cloud);
      clouds.push({ group: cloud, speed: 0.045 + Math.random() * 0.035 });
    }

    createCloud(-7, 4.2, -9, 1.25);
    createCloud(2.5, 5.8, -13, 1.6);
    createCloud(8, 3.8, -10, 1.0);
    createCloud(-11, 2.1, -15, 1.4);
    createCloud(12, 1.4, -17, 1.2);

    const mountainMaterial = new THREE.MeshStandardMaterial({
      color: 0x8eafb5,
      roughness: 1,
      flatShading: true
    });

    for (let i = 0; i < 7; i++) {
      const height = 1.8 + (i % 3) * 0.7;
      const radius = 2.8 + (i % 2) * 1.1;

      const mountain = new THREE.Mesh(
        new THREE.ConeGeometry(radius, height, 5),
        mountainMaterial
      );

      mountain.position.set(
        -9 + i * 3.3,
        height * 0.5 - 1.4,
        -15 - (i % 2) * 1.5
      );

      mountain.rotation.y = i * 0.61;
      scene.add(mountain);
    }

    const birds = [];
    const birdMaterial = new THREE.LineBasicMaterial({
      color: 0x52707b,
      transparent: true,
      opacity: 0.52
    });

    function createBird(x, y, z, scale) {
      const geometry = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(-0.22, 0, 0),
        new THREE.Vector3(0, -0.13, 0),
        new THREE.Vector3(0.22, 0, 0),
        new THREE.Vector3(0, -0.08, 0)
      ]);

      const bird = new THREE.Line(geometry, birdMaterial);
      bird.position.set(x, y, z);
      bird.scale.setScalar(scale);
      scene.add(bird);

      birds.push({
        group: bird,
        speed: 0.16 + Math.random() * 0.12,
        amplitude: 0.12 + Math.random() * 0.12
      });
    }

    createBird(-3.8, 2.2, -3.5, 0.9);
    createBird(3.5, 3.0, -4.2, 0.65);
    createBird(-5.5, 4.0, -6.0, 0.45);

    const particleCount = 90;
    const particlePositions = new Float32Array(particleCount * 3);
    const particleSpeeds = new Float32Array(particleCount);

    for (let i = 0; i < particleCount; i++) {
      particlePositions[i * 3] = (Math.random() - 0.5) * 12;
      particlePositions[i * 3 + 1] = Math.random() * 7 - 0.5;
      particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 5;
      particleSpeeds[i] = 0.08 + Math.random() * 0.18;
    }

    const particleGeometry = new THREE.BufferGeometry();
    particleGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(particlePositions, 3)
    );

    const windParticles = new THREE.Points(
      particleGeometry,
      new THREE.PointsMaterial({
        color: 0xffffff,
        size: 0.028,
        transparent: true,
        opacity: 0.48,
        depthWrite: false
      })
    );

    scene.add(windParticles);

    // A soft sun disc in the distance.
    const sunDisc = new THREE.Mesh(
      new THREE.CircleGeometry(1.05, 48),
      new THREE.MeshBasicMaterial({
        color: 0xffe3a5,
        side: THREE.DoubleSide
      })
    );

    sunDisc.position.set(-5.5, 4.2, -12);
    scene.add(sunDisc);

    // ---------------------------------------------------------------------
    // Custom orbit controls
    // ---------------------------------------------------------------------

    const target = new THREE.Vector3(0.45, -0.18, 0);

    const initialView = {
      radius: 10.4,
      phi: 1.22,
      theta: 0.34
    };

    const desired = { ...initialView };
    const current = { ...initialView };

    let dragging = false;
    let pointerX = 0;
    let pointerY = 0;

    function clampView() {
      desired.phi = THREE.MathUtils.clamp(desired.phi, 0.38, 1.48);
      desired.radius = THREE.MathUtils.clamp(desired.radius, 5.4, 16);
    }

    function resetView() {
      desired.radius = initialView.radius;
      desired.phi = initialView.phi;
      desired.theta = initialView.theta;
    }

    renderer.domElement.addEventListener("pointerdown", (event) => {
      dragging = true;
      pointerX = event.clientX;
      pointerY = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
      renderer.domElement.focus({ preventScroll: true });
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!dragging) return;

      const deltaX = event.clientX - pointerX;
      const deltaY = event.clientY - pointerY;

      pointerX = event.clientX;
      pointerY = event.clientY;

      desired.theta -= deltaX * 0.006;
      desired.phi -= deltaY * 0.005;

      clampView();
    });

    function endDrag(event) {
      dragging = false;

      if (
        event.pointerId !== undefined &&
        renderer.domElement.hasPointerCapture(event.pointerId)
      ) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    }

    renderer.domElement.addEventListener("pointerup", endDrag);
    renderer.domElement.addEventListener("pointercancel", endDrag);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        desired.radius *= Math.exp(event.deltaY * 0.001);
        clampView();
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", resetView);
    resetButton.addEventListener("click", resetView);

    window.addEventListener("keydown", (event) => {
      const key = event.key.toLowerCase();

      if (key === "r") {
        resetView();
      } else if (key === "arrowleft") {
        desired.theta -= 0.08;
      } else if (key === "arrowright") {
        desired.theta += 0.08;
      } else if (key === "arrowup") {
        desired.phi -= 0.05;
      } else if (key === "arrowdown") {
        desired.phi += 0.05;
      } else if (key === "+" || key === "=") {
        desired.radius -= 0.4;
      } else if (key === "-" || key === "_") {
        desired.radius += 0.4;
      } else {
        return;
      }

      clampView();
      event.preventDefault();
    });

    function updateCamera(delta) {
      const smoothing = 1 - Math.exp(-delta * 8);

      current.radius += (desired.radius - current.radius) * smoothing;
      current.phi += (desired.phi - current.phi) * smoothing;
      current.theta += (desired.theta - current.theta) * smoothing;

      const spherical = new THREE.Spherical(
        current.radius,
        current.phi,
        current.theta
      );

      camera.position.setFromSpherical(spherical).add(target);
      camera.lookAt(target);
    }

    // ---------------------------------------------------------------------
    // Animation
    // ---------------------------------------------------------------------

    const clock = new THREE.Clock();
    const windTime = { value: 0 };

    function animate() {
      requestAnimationFrame(animate);

      const delta = Math.min(clock.getDelta(), 0.05);
      const time = windTime.value;
      windTime.value += delta;

      if (!reducedMotion) {
        // Gentle airborne motion.
        kite.position.y = 1.15 + Math.sin(time * 0.72) * 0.075;
        kite.rotation.z = Math.sin(time * 0.48) * 0.028;
        kite.rotation.x = Math.sin(time * 0.37 + 1.2) * 0.022;
        kite.rotation.y = Math.sin(time * 0.31) * 0.025;

        spool.rotation.x = time * 0.85;
        sunDisc.lookAt(
          camera.position.x,
          camera.position.y,
          camera.position.z
        );

        for (const cloud of clouds) {
          cloud.group.position.x += cloud.speed * delta;

          if (cloud.group.position.x > 14) {
            cloud.group.position.x = -14;
          }
        }

        for (const bird of birds) {
          bird.group.position.x += bird.speed * delta;
          bird.group.position.y +=
            Math.sin(time * 0.7 + bird.group.position.x) *
            delta *
            0.08;

          if (bird.group.position.x > 8) {
            bird.group.position.x = -8;
          }
        }

        const positions = particleGeometry.attributes.position.array;

        for (let i = 0; i < particleCount; i++) {
          const index = i * 3;

          positions[index] += particleSpeeds[i] * delta;
          positions[index + 1] += Math.sin(time * 0.8 + i) * delta * 0.035;

          if (positions[index] > 6.5) {
            positions[index] = -6.5;
          }
        }

        particleGeometry.attributes.position.needsUpdate = true;
      }

      updateCamera(delta);
      renderer.render(scene, camera);
    }

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    updateCamera(1);
    animate();
  </script>
